//! Minimal terminal size detection used by the help renderer.

use std::os::unix::io::{AsRawFd, RawFd};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

fn size_of_fd(fd: RawFd) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == -1 {
            return None;
        }
        let rows = ws.ws_row;
        let cols = ws.ws_col;
        if rows > 0 && cols > 0 {
            Some((Width(cols), Height(rows)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal attached to the given handle.
pub fn terminal_size_of<F: AsRawFd>(fd: F) -> Option<(Width, Height)> {
    size_of_fd(fd.as_raw_fd())
}

/// Returns the size of the terminal, checking stdout, stderr and stdin in that order.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(libc::STDOUT_FILENO)
        .or_else(|| size_of_fd(libc::STDERR_FILENO))
        .or_else(|| size_of_fd(libc::STDIN_FILENO))
}
EOF
cat > .gitignore <<'EOF'
/target
/executable
*.o
EOF
echo ok"}

