//! Terminal styles and ANSI escape code generation.

use serde::Deserialize;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Color {
    Default,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
}

impl Color {
    fn fg_code(self) -> u8 {
        match self {
            Color::Default => 39,
            Color::Black => 30,
            Color::Red => 31,
            Color::Green => 32,
            Color::Yellow => 33,
            Color::Blue => 34,
            Color::Magenta => 35,
            Color::Cyan => 36,
            Color::White => 37,
            Color::BrightBlack => 90,
            Color::BrightRed => 91,
            Color::BrightGreen => 92,
            Color::BrightYellow => 93,
            Color::BrightBlue => 94,
            Color::BrightMagenta => 95,
            Color::BrightCyan => 96,
            Color::BrightWhite => 97,
        }
    }

    fn bg_code(self) -> u8 {
        match self {
            Color::Default => 49,
            other => other.fg_code() + 10,
        }
    }
}

/// A text style. The field order matters: styles are ordered by
/// (fg, bg, bold, faint, italic, underline).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash, Deserialize)]
pub struct Style {
    #[serde(default)]
    pub fg: Option<Color>,
    #[serde(default)]
    pub bg: Option<Color>,
    #[serde(default)]
    pub bold: bool,
    #[serde(default)]
    pub faint: bool,
    #[serde(default)]
    pub italic: bool,
    #[serde(default)]
    pub underline: bool,
}

pub const RESET: &str = "\x1b[0m";

impl Style {
    pub const fn new() -> Style {
        Style {
            fg: None,
            bg: None,
            bold: false,
            faint: false,
            italic: false,
            underline: false,
        }
    }

    pub const fn fg(mut self, c: Color) -> Style {
        self.fg = Some(c);
        self
    }

    pub const fn on(mut self, c: Color) -> Style {
        self.bg = Some(c);
        self
    }

    pub const fn faint(mut self) -> Style {
        self.faint = true;
        self
    }

    pub const fn italic(mut self) -> Style {
        self.italic = true;
        self
    }

    pub fn is_plain(&self) -> bool {
        self.fg.is_none()
            && self.bg.is_none()
            && !self.bold
            && !self.faint
            && !self.italic
            && !self.underline
    }

    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut codes: Vec<String> = Vec::new();
        if self.bold {
            codes.push("1".into());
        }
        if self.faint {
            codes.push("2".into());
        }
        if self.italic {
            codes.push("3".into());
        }
        if self.underline {
            codes.push("4".into());
        }
        if let Some(bg) = self.bg {
            codes.push(bg.bg_code().to_string());
        }
        if let Some(fg) = self.fg {
            codes.push(fg.fg_code().to_string());
        }
        format!("\x1b[{}m", codes.join(";"))
    }

    /// Append `text` painted with this style to `out`.
    pub fn paint_into(&self, out: &mut String, text: &str) {
        if self.is_plain() {
            out.push_str(text);
        } else {
            out.push_str(&self.prefix());
            out.push_str(text);
            out.push_str(RESET);
        }
    }

    pub fn paint(&self, text: &str) -> String {
        let mut s = String::with_capacity(text.len() + 12);
        self.paint_into(&mut s, text);
        s
    }
}
EOF
echo ok"}

