//! The highlighting engine: a sequence of highlighters, each applied only to
//! the parts of a line that have not been highlighted yet.

use crate::style::Style;
use crate::theme::*;
use regex::Regex;
use std::collections::BTreeMap;

pub trait Highlight {
    /// Highlight a chunk of text that does not contain any escape sequences
    /// produced by earlier highlighters.
    fn apply(&self, input: &str) -> String;
}

pub struct Highlighter {
    highlighters: Vec<Box<dyn Highlight>>,
}

/// Split a string into alternating (unhighlighted, highlighted) chunks.
/// A highlighted chunk starts at an escape sequence introducer (`ESC [`) and
/// extends to the end of the next reset sequence (`ESC [0m`), or to the end of
/// the input if there is none.
fn for_each_chunk<F: FnMut(&str, bool)>(input: &str, mut f: F) {
    const START: &str = "\x1b[";
    const END: &str = "\x1b[0m";
    let mut pos = 0;
    while pos < input.len() {
        match input[pos..].find(START) {
            None => {
                f(&input[pos..], false);
                return;
            }
            Some(rel) => {
                let start = pos + rel;
                if start > pos {
                    f(&input[pos..start], false);
                }
                match input[start..].find(END) {
                    Some(rel_end) => {
                        let end = start + rel_end + END.len();
                        f(&input[start..end], true);
                        pos = end;
                    }
                    None => {
                        f(&input[start..], true);
                        return;
                    }
                }
            }
        }
    }
}

fn apply_to_unhighlighted(h: &dyn Highlight, input: &str) -> String {
    let mut out = String::with_capacity(input.len() + 16);
    for_each_chunk(input, |chunk, highlighted| {
        if highlighted {
            out.push_str(chunk);
        } else {
            out.push_str(&h.apply(chunk));
        }
    });
    out
}

impl Highlighter {
    pub fn apply(&self, line: &str) -> String {
        let mut current = line.to_string();
        for h in &self.highlighters {
            current = apply_to_unhighlighted(h.as_ref(), &current);
        }
        current
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Groups {
    pub numbers: bool,
    pub urls: bool,
    pub pointers: bool,
    pub dates: bool,
    pub paths: bool,
    pub quotes: bool,
    pub key_value_pairs: bool,
    pub uuids: bool,
    pub ip_addresses: bool,
    pub processes: bool,
    pub json: bool,
}

impl Groups {
    pub fn all(value: bool) -> Groups {
        Groups {
            numbers: value,
            urls: value,
            pointers: value,
            dates: value,
            paths: value,
            quotes: value,
            key_value_pairs: value,
            uuids: value,
            ip_addresses: value,
            processes: value,
            json: value,
        }
    }

    pub fn set(&mut self, name: &str, value: bool) {
        match name {
            "numbers" => self.numbers = value,
            "urls" => self.urls = value,
            "pointers" => self.pointers = value,
            "dates" => self.dates = value,
            "paths" => self.paths = value,
            "quotes" => self.quotes = value,
            "key-value-pairs" => self.key_value_pairs = value,
            "uuids" => self.uuids = value,
            "ip-addresses" => self.ip_addresses = value,
            "processes" => self.processes = value,
            "json" => self.json = value,
            _ => {}
        }
    }
}

pub fn build(
    theme: &Theme,
    groups: Groups,
    keywords: Vec<KeywordToml>,
) -> Result<Highlighter, regex::Error> {
    let mut hs: Vec<Box<dyn Highlight>> = Vec::new();

    if groups.json {
        hs.push(Box::new(JsonHighlighter {
            theme: theme.json.clone(),
        }));
    }
    for r in &theme.regexes {
        let regex = Regex::new(&r.regex)?;
        hs.push(Box::new(RegexHighlighter {
            regex,
            style: r.style,
        }));
    }
    if groups.dates {
        hs.push(Box::new(TimeHighlighter::new(theme.dates.clone())));
        hs.push(Box::new(DateHighlighter::new(theme.dates.clone())));
    }
    if groups.ip_addresses {
        hs.push(Box::new(Ipv6Highlighter::new(theme.ips.clone())));
        hs.push(Box::new(Ipv4Highlighter::new(theme.ips.clone())));
    }
    if groups.urls {
        hs.push(Box::new(UrlHighlighter::new(theme.urls.clone())));
    }
    if groups.paths {
        hs.push(Box::new(PathHighlighter::new(theme.paths.clone())));
    }
    if groups.key_value_pairs {
        hs.push(Box::new(KeyValueHighlighter::new(theme.key_values.clone())));
    }
    if groups.uuids {
        hs.push(Box::new(UuidHighlighter::new(theme.uuids.clone())));
    }
    if groups.pointers {
        hs.push(Box::new(PointerHighlighter::new(theme.pointers.clone())));
    }
    if groups.processes {
        hs.push(Box::new(ProcessHighlighter::new(theme.processes.clone())));
    }
    if groups.numbers {
        hs.push(Box::new(NumberHighlighter::new(theme.numbers.clone())));
    }

    // Keywords: grouped by style, applied in style order.
    let mut by_style: BTreeMap<Style, Vec<String>> = BTreeMap::new();
    for kw in keywords {
        by_style.entry(kw.style).or_default().extend(kw.words);
    }
    for (style, mut words) in by_style {
        words.sort();
        words.dedup();
        hs.push(Box::new(KeywordHighlighter::new(words, style)));
    }

    if groups.quotes {
        hs.push(Box::new(QuoteHighlighter {
            theme: theme.quotes.clone(),
        }));
    }

    Ok(Highlighter { highlighters: hs })
}

// ---------------------------------------------------------------------------
// Helpers

fn is_ascii_word(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Generic regex based replacement: `f` renders a match into `out`.
fn replace_all<F>(regex: &Regex, input: &str, mut f: F) -> String
where
    F: FnMut(&regex::Captures, &mut String),
{
    let mut out = String::with_capacity(input.len() + 32);
    let mut last = 0;
    for caps in regex.captures_iter(input) {
        let m = caps.get(0).unwrap();
        out.push_str(&input[last..m.start()]);
        f(&caps, &mut out);
        last = m.end();
    }
    out.push_str(&input[last..]);
    out
}

fn paint_hex_chars(out: &mut String, text: &str, number: &Style, letter: &Style, sep: &Style) {
    for c in text.chars() {
        let mut buf = [0u8; 4];
        let s = c.encode_utf8(&mut buf);
        if c.is_ascii_digit() {
            number.paint_into(out, s);
        } else if c.is_ascii_alphabetic() {
            letter.paint_into(out, s);
        } else {
            sep.paint_into(out, s);
        }
    }
}

// ---------------------------------------------------------------------------
// JSON

struct JsonHighlighter {
    theme: JsonTheme,
}

impl JsonHighlighter {
    fn render(&self, v: &serde_json::Value, out: &mut String) {
        use serde_json::Value;
        let t = &self.theme;
        match v {
            Value::Null => out.push_str("null"),
            Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Value::Number(n) => out.push_str(&n.to_string()),
            Value::String(s) => {
                t.quote_token.paint_into(out, "\"");
                out.push_str(s);
                t.quote_token.paint_into(out, "\"");
            }
            Value::Array(items) => {
                t.square_bracket.paint_into(out, "[");
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        t.comma.paint_into(out, ",");
                        out.push(' ');
                    }
                    self.render(item, out);
                }
                t.square_bracket.paint_into(out, "]");
            }
            Value::Object(map) => {
                t.curly_bracket.paint_into(out, "{");
                out.push(' ');
                for (i, (k, val)) in map.iter().enumerate() {
                    if i > 0 {
                        t.comma.paint_into(out, ",");
                        out.push(' ');
                    }
                    t.quote_token.paint_into(out, "\"");
                    t.key.paint_into(out, k);
                    t.quote_token.paint_into(out, "\"");
                    t.colon.paint_into(out, ":");
                    out.push(' ');
                    self.render(val, out);
                }
                if !map.is_empty() {
                    out.push(' ');
                }
                t.curly_bracket.paint_into(out, "}");
            }
        }
    }
}

impl Highlight for JsonHighlighter {
    fn apply(&self, input: &str) -> String {
        match serde_json::from_str::<serde_json::Value>(input) {
            Ok(v) => {
                let mut out = String::with_capacity(input.len() * 2);
                self.render(&v, &mut out);
                out
            }
            Err(_) => input.to_string(),
        }
    }
}

// ---------------------------------------------------------------------------
// Custom regexes

struct RegexHighlighter {
    regex: Regex,
    style: Style,
}

impl Highlight for RegexHighlighter {
    fn apply(&self, input: &str) -> String {
        let single_group = self.regex.captures_len() == 2;
        let style = self.style;
        replace_all(&self.regex, input, |caps, out| {
            let m = caps.get(0).unwrap();
            if single_group {
                if let Some(g) = caps.get(1) {
                    out.push_str(&input[m.start()..g.start()]);
                    style.paint_into(out, g.as_str());
                    out.push_str(&input[g.end()..m.end()]);
                }
            } else {
                style.paint_into(out, m.as_str());
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Time

struct TimeHighlighter {
    regex: Regex,
    theme: DateTheme,
}

impl TimeHighlighter {
    fn new(theme: DateTheme) -> Self {
        let regex = Regex::new(
            r"(?P<T>[T ])?(?P<h>[01]?[0-9]|2[0-3])(?P<c1>:)(?P<m>[0-5][0-9])(?P<c2>:)(?P<s>[0-5][0-9])(?P<fs>[.,:])?(?P<f>[0-9]+)?(?P<z>Z)?",
        )
        .unwrap();
        TimeHighlighter { regex, theme }
    }
}

impl Highlight for TimeHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            if let Some(m) = caps.name("T") {
                t.zone.paint_into(out, m.as_str());
            }
            t.time.paint_into(out, &caps["h"]);
            t.separator.paint_into(out, &caps["c1"]);
            t.time.paint_into(out, &caps["m"]);
            t.separator.paint_into(out, &caps["c2"]);
            t.time.paint_into(out, &caps["s"]);
            if let Some(m) = caps.name("fs") {
                t.separator.paint_into(out, m.as_str());
            }
            if let Some(m) = caps.name("f") {
                t.time.paint_into(out, m.as_str());
            }
            if let Some(m) = caps.name("z") {
                t.zone.paint_into(out, m.as_str());
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Date

struct DateHighlighter {
    regex: Regex,
    theme: DateTheme,
}

impl DateHighlighter {
    fn new(theme: DateTheme) -> Self {
        let regex = Regex::new(concat!(
            r"(?P<y1>(?:19|20)[0-9]{2})(?P<s1>[-/])(?P<a1>0[1-9]|1[0-2])(?P<s2>[-/])(?P<b1>0[1-9]|[12][0-9]|3[01])",
            r"|(?P<a2>0[1-9]|[12][0-9]|3[01])(?P<s3>[-/])(?P<b2>0[1-9]|[12][0-9]|3[01])(?P<s4>[-/])(?P<y2>(?:19|20)[0-9]{2})"
        ))
        .unwrap();
        DateHighlighter { regex, theme }
    }
}

impl Highlight for DateHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            let (y, s1, a, s2, b) = if caps.name("y1").is_some() {
                (&caps["y1"], &caps["s1"], &caps["a1"], &caps["s2"], &caps["b1"])
            } else {
                (&caps["y2"], &caps["s3"], &caps["a2"], &caps["s4"], &caps["b2"])
            };
            t.date.paint_into(out, y);
            t.separator.paint_into(out, s1);
            t.date.paint_into(out, a);
            t.separator.paint_into(out, s2);
            t.date.paint_into(out, b);
        })
    }
}

// ---------------------------------------------------------------------------
// IPv6

struct Ipv6Highlighter {
    regex: Regex,
    theme: IpTheme,
}

impl Ipv6Highlighter {
    fn new(theme: IpTheme) -> Self {
        let regex =
            Regex::new(r"(?P<ip>[0-9a-fA-F:.]*[0-9a-fA-F][0-9a-fA-F:.]*)(?:(?P<slash>/)(?P<cidr>[0-9]{1,3}))?")
                .unwrap();
        Ipv6Highlighter { regex, theme }
    }
}

impl Highlight for Ipv6Highlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            let ip = &caps["ip"];
            let whole = caps.get(0).unwrap().as_str();
            if !ip.contains(':') || ip.parse::<std::net::Ipv6Addr>().is_err() {
                out.push_str(whole);
                return;
            }
            paint_hex_chars(out, ip, &t.number, &t.letter, &t.separator);
            if let Some(slash) = caps.name("slash") {
                t.separator.paint_into(out, slash.as_str());
                t.number.paint_into(out, &caps["cidr"]);
            }
        })
    }
}

// ---------------------------------------------------------------------------
// IPv4

struct Ipv4Highlighter {
    regex: Regex,
    theme: IpTheme,
}

impl Ipv4Highlighter {
    fn new(theme: IpTheme) -> Self {
        let regex = Regex::new(
            r"(?-u:\b)(?P<a>[0-9]{1,3})\.(?P<b>[0-9]{1,3})\.(?P<c>[0-9]{1,3})\.(?P<d>[0-9]{1,3})(?:/(?P<cidr>[0-9]{1,2}))?(?-u:\b)",
        )
        .unwrap();
        Ipv4Highlighter { regex, theme }
    }
}

impl Highlight for Ipv4Highlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            let whole = caps.get(0).unwrap().as_str();
            let octets = [&caps["a"], &caps["b"], &caps["c"], &caps["d"]];
            let valid_octets = octets.iter().all(|o| o.parse::<u32>().map(|v| v <= 255).unwrap_or(false));
            let valid_cidr = caps
                .name("cidr")
                .map(|c| c.as_str().parse::<u32>().map(|v| v <= 32).unwrap_or(false))
                .unwrap_or(true);
            if !valid_octets || !valid_cidr {
                out.push_str(whole);
                return;
            }
            for (i, o) in octets.iter().enumerate() {
                if i > 0 {
                    t.separator.paint_into(out, ".");
                }
                t.number.paint_into(out, o);
            }
            if let Some(c) = caps.name("cidr") {
                t.separator.paint_into(out, "/");
                t.number.paint_into(out, c.as_str());
            }
        })
    }
}

// ---------------------------------------------------------------------------
// URLs

struct UrlHighlighter {
    regex: Regex,
    query: Regex,
    theme: UrlTheme,
}

impl UrlHighlighter {
    fn new(theme: UrlTheme) -> Self {
        let regex = Regex::new(
            r"(?P<protocol>https?)://(?P<host>[A-Za-z0-9_.\-]+)(?P<path>/[A-Za-z0-9_\-./%+~]*)?(?P<query>\?[A-Za-z0-9_!%&'()*+,\-./:;=?@~]*)?",
        )
        .unwrap();
        let query =
            Regex::new(r"(?P<delim>[?&])(?P<key>[A-Za-z0-9_%+\-.~]*)(?P<eq>=)(?P<value>[A-Za-z0-9_%+\-.~]*)").unwrap();
        UrlHighlighter {
            regex,
            query,
            theme,
        }
    }
}

impl Highlight for UrlHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            let protocol = &caps["protocol"];
            if protocol == "https" {
                t.https.paint_into(out, protocol);
            } else {
                t.http.paint_into(out, protocol);
            }
            out.push_str("://");
            t.host.paint_into(out, &caps["host"]);
            let path = caps.name("path").map(|m| m.as_str()).unwrap_or("");
            t.path.paint_into(out, path);
            if let Some(q) = caps.name("query") {
                let q = q.as_str();
                let rendered = replace_all(&self.query, q, |qc, qout| {
                    t.symbols.paint_into(qout, &qc["delim"]);
                    t.query_params_key.paint_into(qout, &qc["key"]);
                    t.symbols.paint_into(qout, &qc["eq"]);
                    t.query_params_value.paint_into(qout, &qc["value"]);
                });
                out.push_str(&rendered);
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Unix paths

struct PathHighlighter {
    regex: Regex,
    theme: PathTheme,
}

impl PathHighlighter {
    fn new(theme: PathTheme) -> Self {
        let regex = Regex::new(r"(?:~|/|[A-Za-z0-9_.\-]+)?(?:/[A-Za-z0-9_.\-]+){2,}").unwrap();
        PathHighlighter { regex, theme }
    }
}

impl Highlight for PathHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            let path = caps.get(0).unwrap().as_str();
            let mut seg_start = 0;
            for (i, c) in path.char_indices() {
                if c == '/' {
                    if i > seg_start {
                        t.segment.paint_into(out, &path[seg_start..i]);
                    }
                    t.separator.paint_into(out, "/");
                    seg_start = i + 1;
                }
            }
            if seg_start < path.len() {
                t.segment.paint_into(out, &path[seg_start..]);
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Key-value pairs

struct KeyValueHighlighter {
    regex: Regex,
    theme: KeyValueTheme,
}

impl KeyValueHighlighter {
    fn new(theme: KeyValueTheme) -> Self {
        let regex = Regex::new(r"(?P<ws>^|[\t\n\x0B\x0C\r ])(?P<key>[A-Za-z0-9_]+)(?P<eq>=)").unwrap();
        KeyValueHighlighter { regex, theme }
    }
}

impl Highlight for KeyValueHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            out.push_str(&caps["ws"]);
            t.key.paint_into(out, &caps["key"]);
            t.separator.paint_into(out, &caps["eq"]);
        })
    }
}

// ---------------------------------------------------------------------------
// UUIDs

struct UuidHighlighter {
    regex: Regex,
    theme: UuidTheme,
}

impl UuidHighlighter {
    fn new(theme: UuidTheme) -> Self {
        let regex = Regex::new(
            r"(?-u:\b)[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(?-u:\b)",
        )
        .unwrap();
        UuidHighlighter { regex, theme }
    }
}

impl Highlight for UuidHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            paint_hex_chars(out, caps.get(0).unwrap().as_str(), &t.number, &t.letter, &t.dash);
        })
    }
}

// ---------------------------------------------------------------------------
// Pointers

struct PointerHighlighter {
    regex: Regex,
    theme: PointerTheme,
}

impl PointerHighlighter {
    fn new(theme: PointerTheme) -> Self {
        let regex =
            Regex::new(r"(?-u:\b)(?P<zero>0)(?P<x>[xX])(?P<hex>[0-9a-fA-F]{16}|[0-9a-fA-F]{8})(?-u:\b)").unwrap();
        PointerHighlighter { regex, theme }
    }
}

impl Highlight for PointerHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            t.number.paint_into(out, &caps["zero"]);
            t.x.paint_into(out, &caps["x"]);
            let hex = &caps["hex"];
            let none = Style::new();
            if hex.len() == 16 {
                paint_hex_chars(out, &hex[..8], &t.number, &t.letter, &none);
                let mut buf = [0u8; 4];
                t.separator.paint_into(out, t.separator_token.encode_utf8(&mut buf));
                paint_hex_chars(out, &hex[8..], &t.number, &t.letter, &none);
            } else {
                paint_hex_chars(out, hex, &t.number, &t.letter, &none);
            }
        })
    }
}

// ---------------------------------------------------------------------------
// Unix processes

struct ProcessHighlighter {
    regex: Regex,
    theme: ProcessTheme,
}

impl ProcessHighlighter {
    fn new(theme: ProcessTheme) -> Self {
        let regex = Regex::new(r"(?P<name>[A-Za-z0-9_\-/()]+)(?P<open>\[)(?P<id>[0-9]+)(?P<close>\])").unwrap();
        ProcessHighlighter { regex, theme }
    }
}

impl Highlight for ProcessHighlighter {
    fn apply(&self, input: &str) -> String {
        let t = &self.theme;
        replace_all(&self.regex, input, |caps, out| {
            t.name.paint_into(out, &caps["name"]);
            t.bracket.paint_into(out, &caps["open"]);
            t.id.paint_into(out, &caps["id"]);
            t.bracket.paint_into(out, &caps["close"]);
        })
    }
}

// ---------------------------------------------------------------------------
// Numbers

struct NumberHighlighter {
    regex: Regex,
    theme: NumberTheme,
}

impl NumberHighlighter {
    fn new(theme: NumberTheme) -> Self {
        let regex = Regex::new(r"(?-u:\b)[0-9]+(?:\.[0-9]+)?(?-u:\b)").unwrap();
        NumberHighlighter { regex, theme }
    }
}

impl Highlight for NumberHighlighter {
    fn apply(&self, input: &str) -> String {
        let style = self.theme.number;
        replace_all(&self.regex, input, |caps, out| {
            style.paint_into(out, caps.get(0).unwrap().as_str());
        })
    }
}

// ---------------------------------------------------------------------------
// Keywords

struct KeywordHighlighter {
    regex: Regex,
    style: Style,
}

impl KeywordHighlighter {
    fn new(words: Vec<String>, style: Style) -> Self {
        let pattern = words
            .iter()
            .map(|w| regex::escape(w))
            .collect::<Vec<_>>()
            .join("|");
        let regex = Regex::new(&pattern).unwrap_or_else(|_| Regex::new("$^").unwrap());
        KeywordHighlighter { regex, style }
    }
}

impl Highlight for KeywordHighlighter {
    fn apply(&self, input: &str) -> String {
        let mut out = String::with_capacity(input.len() + 16);
        let mut last = 0;
        let padded = self.style.bg.is_some();
        for m in self.regex.find_iter(input) {
            let before_ok = input[..m.start()]
                .chars()
                .next_back()
                .map(|c| !is_ascii_word(c))
                .unwrap_or(true);
            let after_ok = input[m.end()..]
                .chars()
                .next()
                .map(|c| !is_ascii_word(c))
                .unwrap_or(true);
            if !(before_ok && after_ok) {
                continue;
            }
            out.push_str(&input[last..m.start()]);
            if padded {
                self.style.paint_into(&mut out, &format!(" {} ", m.as_str()));
            } else {
                self.style.paint_into(&mut out, m.as_str());
            }
            last = m.end();
        }
        out.push_str(&input[last..]);
        out
    }
}

// ---------------------------------------------------------------------------
// Quotes

struct QuoteHighlighter {
    theme: QuoteTheme,
}

impl Highlight for QuoteHighlighter {
    fn apply(&self, input: &str) -> String {
        let token = self.theme.token;
        let count = input.chars().filter(|&c| c == token).count();
        if count == 0 || count % 2 != 0 {
            return input.to_string();
        }
        let mut out = String::with_capacity(input.len() + 16);
        let mut open: Option<usize> = None;
        let mut last = 0;
        for (i, c) in input.char_indices() {
            if c != token {
                continue;
            }
            match open {
                None => {
                    out.push_str(&input[last..i]);
                    open = Some(i);
                }
                Some(start) => {
                    let end = i + c.len_utf8();
                    self.theme.style.paint_into(&mut out, &input[start..end]);
                    last = end;
                    open = None;
                }
            }
        }
        out.push_str(&input[last..]);
        out
    }
}
