//! A small line wrapping implementation used for error reports.
//!
//! Lines are split into words at Unicode line break opportunities, words are
//! additionally split after hyphens, overlong words are broken apart and the
//! words are then distributed over lines using a first-fit strategy.

fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    // Combining marks and zero width characters.
    if (0x0300..=0x036f).contains(&cp)
        || (0x200b..=0x200f).contains(&cp)
        || (0xfe00..=0xfe0f).contains(&cp)
        || cp == 0x00ad
    {
        return 0;
    }
    // Wide (East Asian) characters.
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x2fffd).contains(&cp)
        || (0x30000..=0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

/// If `ch` starts an ANSI escape sequence, consume the rest of it from
/// `chars` and return true.
fn skip_ansi<I: Iterator<Item = char>>(ch: char, chars: &mut I) -> bool {
    if ch != '\x1b' {
        return false;
    }
    match chars.next() {
        Some('[') => {
            for c in chars {
                if ('\x40'..='\x7e').contains(&c) {
                    return true;
                }
            }
        }
        Some(']') => {
            let mut last = None;
            for c in chars {
                if c == '\x07' || (c == '\\' && last == Some('\x1b')) {
                    return true;
                }
                last = Some(c);
            }
        }
        _ => {}
    }
    true
}

pub fn display_width(text: &str) -> usize {
    let mut chars = text.chars();
    let mut width = 0;
    while let Some(ch) = chars.next() {
        if skip_ansi(ch, &mut chars) {
            continue;
        }
        width += char_width(ch);
    }
    width
}

fn strip_ansi(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars();
    while let Some(ch) = chars.next() {
        if skip_ansi(ch, &mut chars) {
            continue;
        }
        out.push(ch);
    }
    out
}

