// Unicode line breaking (UAX #14), simplified.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Lb {
    BK,
    CR,
    LF,
    SP,
    ZW,
    GL,
    WJ,
    CM,
    AL,
    NU,
    IS,
    SY,
    OP,
    CP,
    CL,
    QU,
    EX,
    HY,
    BA,
    BB,
    NS,
    PR,
    PO,
    ID,
    IN,
}

fn class_of(c: char) -> Lb {
    use Lb::*;
    match c {
        '\n' | '\u{85}' => LF,
        '\r' => CR,
        '\u{0b}' | '\u{0c}' | '\u{2028}' | '\u{2029}' => BK,
        ' ' => SP,
        '\t' => BA,
        '!' | '?' => EX,
        '"' | '\'' => QU,
        '$' | '+' | '\\' => PR,
        '%' => PO,
        '(' | '[' | '{' => OP,
        ')' | ']' => CP,
        '}' => CL,
        ',' | '.' | ':' | ';' => IS,
        '-' => HY,
        '/' => SY,
        '0'..='9' => NU,
        '|' => BA,
        '\u{a0}' | '\u{202f}' | '\u{2007}' | '\u{2011}' => GL,
        '\u{200b}' => ZW,
        '\u{2060}' | '\u{feff}' => WJ,
        '\u{ad}' => BA,
        '\u{2010}' | '\u{2012}' | '\u{2013}' => BA,
        '\u{2014}' => BA,
        '\u{2026}' => IN,
        '\u{a2}' | '\u{b0}' | '\u{2030}' | '\u{2032}' | '\u{2033}' => PO,
        '\u{a3}' | '\u{a5}' | '\u{b1}' | '\u{20ac}' => PR,
        '\u{ab}' | '\u{bb}' | '\u{2018}' | '\u{2019}' | '\u{201c}' | '\u{201d}' => QU,
        '\u{a1}' | '\u{bf}' => OP,
        '\u{b4}' => BB,
        '\u{300}'..='\u{36f}' => CM,
        '\u{3001}' | '\u{3002}' | '\u{ff0c}' | '\u{ff0e}' => CL,
        _ => {
            if char_width(c) == 2 {
                ID
            } else {
                AL
            }
        }
    }
}

/// Returns the byte offsets in `text` where a line break is allowed
/// (excluding the start, including the end of the text).
fn linebreaks(text: &str) -> Vec<usize> {
    use Lb::*;
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let mut result = Vec::new();
    if chars.is_empty() {
        return result;
    }
    // Resolve classes (LB9/LB10: combining marks attach to the previous char).
    let mut classes: Vec<Lb> = Vec::with_capacity(chars.len());
    for (i, &(_, c)) in chars.iter().enumerate() {
        let mut cls = class_of(c);
        if cls == CM {
            if i > 0 {
                let prev = classes[i - 1];
                if !matches!(prev, BK | CR | LF | SP | ZW) {
                    cls = prev;
                } else {
                    cls = AL;
                }
            } else {
                cls = AL;
            }
        }
        classes.push(cls);
    }

    for i in 1..chars.len() {
        let before = classes[i - 1];
        let after = classes[i];
        // Class of the last non-space character before position i, if the
        // characters between it and i are all spaces.
        let mut j = i;
        while j > 0 && classes[j - 1] == SP {
            j -= 1;
        }
        let before_sp: Option<Lb> = if j > 0 { Some(classes[j - 1]) } else { None };

        let allowed = (|| {
            // LB4, LB5
            if before == BK {
                return true;
            }
            if before == CR && after == LF {
                return false;
            }
            if before == CR || before == LF {
                return true;
            }
            // LB6
            if matches!(after, BK | CR | LF) {
                return false;
            }
            // LB7
            if matches!(after, SP | ZW) {
                return false;
            }
            // LB8
            if before_sp == Some(ZW) {
                return true;
            }
            // LB11
            if after == WJ || before == WJ {
                return false;
            }
            // LB12
            if before == GL {
                return false;
            }
            // LB12a
            if after == GL && !matches!(before, SP | BA | HY) {
                return false;
            }
            // LB13
            if matches!(after, CL | CP | EX | IS | SY) {
                return false;
            }
            // LB14
            if before_sp == Some(OP) {
                return false;
            }
            // LB15
            if before_sp == Some(QU) && after == OP {
                return false;
            }
            // LB16
            if matches!(before_sp, Some(CL) | Some(CP)) && after == NS {
                return false;
            }
            // LB18
            if before == SP {
                return true;
            }
            // LB19
            if after == QU || before == QU {
                return false;
            }
            // LB21
            if matches!(after, BA | HY | NS) || before == BB {
                return false;
            }
            // LB22
            if after == IN {
                return false;
            }
            // LB23
            if (before == AL && after == NU) || (before == NU && after == AL) {
                return false;
            }
            // LB23a
            if (before == PR && after == ID) || (before == ID && after == PO) {
                return false;
            }
            // LB24
            if matches!(before, PR | PO) && after == AL {
                return false;
            }
            if before == AL && matches!(after, PR | PO) {
                return false;
            }
            // LB25 (simplified pair rules)
            if matches!(before, CL | CP | NU) && matches!(after, PO | PR) {
                return false;
            }
            if matches!(before, PO | PR) && after == OP {
                return false;
            }
            if matches!(before, PO | PR | HY | IS | NU | SY) && after == NU {
                return false;
            }
            // LB28
            if before == AL && after == AL {
                return false;
            }
            // LB29
            if before == IS && after == AL {
                return false;
            }
            // LB30
            if matches!(before, AL | NU) && after == OP {
                return false;
            }
            if before == CP && matches!(after, AL | NU) {
                return false;
            }
            // LB31
            true
        })();
        if allowed {
            result.push(chars[i].0);
        }
    }
    result.push(text.len());
    result
}

