            if before == AL && after == AL {
                return false;
            }
            // LB29
            if before == IS && after == AL {
                return false;
            }
            // LB30
            if matches!(before, AL | NU) && after == OP {
                return false;
            }
            if before == CP && matches!(after, AL | NU) {
                return false;
            }
            // LB31
            true
        })();
        if allowed {
            result.push(chars[i].0);
        }
    }
    result.push(text.len());
    result
}

// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(s: &'a str) -> Word<'a> {
        let trimmed = s.trim_end_matches(' ');
        Word {
            word: trimmed,
            whitespace: &s[trimmed.len()..],
            penalty: "",
            width: display_width(trimmed),
        }
    }
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    // Map from stripped index to original index.
    let mut map: Vec<(usize, usize)> = Vec::new(); // (orig, stripped)
    {
        let mut last_stripped = 0;
        let mut it = line.char_indices().peekable();
        while let Some((orig, ch)) = it.next() {
            let stripped_idx = last_stripped;
            let mut rest = std::iter::from_fn(|| it.next().map(|(_, c)| c));
            if !skip_ansi(ch, &mut rest) {
                last_stripped += ch.len_utf8();
            }
            map.push((orig, stripped_idx));
        }
    }
    let stripped = strip_ansi(line);
    let mut opportunities: Vec<usize> = linebreaks(&stripped)
        .into_iter()
        .filter(|&idx| {
            let prev = stripped[..idx].chars().next_back();
            !matches!(prev, Some('-') | Some('\u{ad}'))
        })
        .collect();
    opportunities.pop();

    let mut words = Vec::new();
    let mut start = 0;
    let mut map_pos = 0;
    for idx in opportunities {
        while map_pos < map.len() && map[map_pos].1 != idx {
            map_pos += 1;
        }
        if map_pos < map.len() {
            let orig = map[map_pos].0;
            map_pos += 1;
            words.push(Word::from(&line[start..orig]));
            start = orig;
        }
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn hyphen_split_points(word: &str) -> Vec<usize> {
    let mut splits = Vec::new();
    for (idx, _) in word.match_indices('-') {
        let prev = word[..idx].chars().next_back();
        let next = word[idx + 1..].chars().next();
        if prev.map(|c| c.is_alphanumeric()).unwrap_or(false)
            && next.map(|c| c.is_alphanumeric()).unwrap_or(false)
        {
            splits.push(idx + 1);
        }
    }
    splits
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    for word in words {
        let points = hyphen_split_points(word.word);
        let mut prev = 0;
        for idx in points {
            let need_hyphen = !word.word[..idx].ends_with('-');
            out.push(Word {
                word: &word.word[prev..idx],
                width: display_width(&word.word[prev..idx]),
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
            });
            prev = idx;
        }
        if prev < word.word.len() || prev == 0 {
            out.push(Word {
                word: &word.word[prev..],
                width: display_width(&word.word[prev..]),
                whitespace: word.whitespace,
                penalty: word.penalty,
            });
        }
    }
    out
}

fn break_apart<'a>(word: Word<'a>, line_width: usize) -> Vec<Word<'a>> {
    let mut out = Vec::new();
    let mut offset = 0;
    let mut width = 0;
    let s = word.word;
    let mut it = s.char_indices().peekable();
    while let Some((idx, ch)) = it.next() {
        let mut rest = std::iter::from_fn(|| it.next().map(|(_, c)| c));
        if skip_ansi(ch, &mut rest) {
            continue;
        }
        let w = char_width(ch);
        if width > 0 && width + w > line_width {
            out.push(Word {
                word: &s[offset..idx],
                width,
                whitespace: "",
                penalty: "",
            });
            offset = idx;
            width = w;
            continue;
        }
        width += w;
    }
    if offset < s.len() {
        out.push(Word {
            word: &s[offset..],
            width,
            whitespace: word.whitespace,
            penalty: word.penalty,
        });
    }
    out
}

fn wrap_single_line<'a>(
    line: &'a str,
    width: usize,
    initial_indent: &str,
    subsequent_indent: &str,
    lines: &mut Vec<String>,
) {
    let initial_width = width.saturating_sub(display_width(initial_indent));
    let subsequent_width = width.saturating_sub(display_width(subsequent_indent));
    let line_widths = [initial_width, subsequent_width];

    let words = find_words(line);
    let split = split_words(words);
    let mut broken: Vec<Word> = Vec::new();
    for w in split {
        if w.width > line_widths[1] {
            broken.extend(break_apart(w, line_widths[1]));
        } else {
            broken.push(w);
        }
    }
    if !initial_indent.is_empty() {
        broken.insert(0, Word::from(""));
    }

    // First fit.
    let mut wrapped: Vec<&[Word]> = Vec::new();
    {
        let mut start = 0;
        let mut w = 0usize;
        for (idx, frag) in broken.iter().enumerate() {
            let lw = *line_widths
                .get(wrapped.len())
                .unwrap_or(&line_widths[1]);
            let penalty_width = display_width(frag.penalty);
            if w + frag.width + penalty_width > lw && idx > start {
                wrapped.push(&broken[start..idx]);
                start = idx;
                w = 0;
            }
            w += frag.width + frag.whitespace.len();
        }
        wrapped.push(&broken[start..]);
    }

    let mut idx = 0;
    for words in wrapped {
        let last = match words.last() {
            None => {
                lines.push(String::new());
                continue;
            }
            Some(w) => *w,
        };
        let len: usize = words
            .iter()
            .map(|w| w.word.len() + w.whitespace.len())
            .sum::<usize>()
            - last.whitespace.len();
        let mut result = if lines.is_empty() && !initial_indent.is_empty() {
            initial_indent.to_string()
        } else if !lines.is_empty() && !subsequent_indent.is_empty() {
            subsequent_indent.to_string()
        } else {
            String::new()
        };
        result.push_str(&line[idx..idx + len]);
        if !last.penalty.is_empty() {
            result.push_str(last.penalty);
        }
        lines.push(result);
        idx += len + last.whitespace.len();
    }
}

/// Wrap `text` to `width` columns, prefixing the first line with
/// `initial_indent` and all following lines with `subsequent_indent`.
pub fn fill(text: &str, width: usize, initial_indent: &str, subsequent_indent: &str) -> String {
    let mut lines: Vec<String> = Vec::new();
    for line in text.split('\n') {
        wrap_single_line(line, width, initial_indent, subsequent_indent, &mut lines);
    }
    lines.join("\n")
}
