//! Rendering of fatal errors in a graphical report format.

use crate::textwrap::fill;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Report {
    pub code: Option<String>,
    pub severity: Severity,
    pub message: String,
    pub causes: Vec<String>,
    pub help: Option<String>,
}

const TERM_WIDTH: usize = 80;

impl Report {
    pub fn new(message: impl Into<String>) -> Report {
        Report {
            code: None,
            severity: Severity::Error,
            message: message.into(),
            causes: Vec::new(),
            help: None,
        }
    }

    pub fn warning(message: impl Into<String>) -> Report {
        let mut r = Report::new(message);
        r.severity = Severity::Warning;
        r
    }

    pub fn with_code(mut self, code: &str) -> Report {
        self.code = Some(code.to_string());
        self
    }

    pub fn with_cause(mut self, cause: impl Into<String>) -> Report {
        self.causes.push(cause.into());
        self
    }

    pub fn with_help(mut self, help: impl Into<String>) -> Report {
        self.help = Some(help.into());
        self
    }

    pub fn render(&self) -> String {
        let width = TERM_WIDTH - 2;
        let mut out = String::new();
        if let Some(code) = &self.code {
            out.push_str(code);
            out.push_str("\n\n");
        }
        let icon = match self.severity {
            Severity::Error => "\u{d7}",
            Severity::Warning => "\u{26a0}",
        };
        let initial = format!("  {} ", icon);
        let rest = "  \u{2502} ";
        out.push_str(&fill(&self.message, width, &initial, rest));
        out.push('\n');
        let n = self.causes.len();
        for (i, cause) in self.causes.iter().enumerate() {
            let is_last = i + 1 == n;
            let ch = if is_last { '\u{2570}' } else { '\u{251c}' };
            let initial = format!("  {}\u{2500}\u{25b6} ", ch);
            let rest = format!("  {}   ", if is_last { ' ' } else { '\u{2502}' });
            out.push_str(&fill(cause, width, &initial, &rest));
            out.push('\n');
        }
        if let Some(help) = &self.help {
            out.push_str(&fill(help, width, "  help: ", "        "));
            out.push('\n');
        }
        out
    }

    /// Print the report to stderr in the same way a returned error from main
    /// would be printed.
    pub fn eprint(&self) {
        use std::io::Write;
        let s = format!("Error: {}\n", self.render());
        let stderr = std::io::stderr();
        let mut lock = stderr.lock();
        let _ = lock.write_all(s.as_bytes());
        let _ = lock.flush();
    }
}
