//! Input readers and output writers.

use crate::highlight::Highlighter;
use crate::report::Report;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;

pub const BUFFER_CAPACITY: usize = 64 * 1024;

/// Where highlighted output goes.
pub enum Sink {
    Stdout,
    File(File),
}

impl Sink {
    pub fn write_batch(&mut self, highlighter: &Highlighter, lines: &[String]) -> io::Result<()> {
        let mut buf = String::new();
        if lines.is_empty() {
            buf.push('\n');
        }
        for line in lines {
            buf.push_str(&highlighter.apply(line));
            buf.push('\n');
        }
        match self {
            Sink::Stdout => {
                let stdout = io::stdout();
                let mut lock = stdout.lock();
                lock.write_all(buf.as_bytes())?;
                lock.flush()
            }
            Sink::File(f) => {
                f.write_all(buf.as_bytes())?;
                f.flush()
            }
        }
    }
}

/// Failure while streaming.
pub enum StreamError {
    Read(io::Error),
    Write(io::Error),
}

/// Read line batches from a stream the same way for stdin and command output:
/// when the buffer holds more than one complete line, all complete lines in the
/// buffer are converted lossily; otherwise a single line is read strictly.
pub fn stream_lines<R: Read>(
    reader: R,
    sink: &mut Sink,
    highlighter: &Highlighter,
) -> Result<(), StreamError> {
    let mut br = BufReader::with_capacity(BUFFER_CAPACITY, reader);
    loop {
        let buf = match br.fill_buf() {
            Ok(b) => b,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(StreamError::Read(e)),
        };
        if buf.is_empty() {
            return Ok(());
        }
        let newlines = buf.iter().filter(|&&b| b == b'\n').count();
        if newlines > 1 {
            let last = buf.iter().rposition(|&b| b == b'\n').unwrap();
            let lines: Vec<String> = buf[..last]
                .split(|&b| b == b'\n')
                .map(|l| String::from_utf8_lossy(l).into_owned())
                .collect();
            br.consume(last + 1);
            sink.write_batch(highlighter, &lines)
                .map_err(StreamError::Write)?;
        } else {
            let mut line = String::new();
            match br.read_line(&mut line) {
                Ok(0) => return Ok(()),
                Ok(_) => {}
                Err(e) => return Err(StreamError::Read(e)),
            }
            if line.ends_with('\n') {
                line.pop();
            }
            sink.write_batch(highlighter, &[line])
                .map_err(StreamError::Write)?;
        }
    }
}

fn strip_cr(mut s: String) -> String {
    if s.ends_with('\r') {
        s.pop();
    }
    s
}

pub fn open_error(path: &Path, e: io::Error) -> Report {
    Report::new(format!("Could not open file: {:?}", path)).with_cause(e.to_string())
}

pub fn initial_read_error() -> Report {
    Report::new("Failed to receive initial-read-complete signal")
        .with_cause("channel closed")
        .with_help("Ensure the IO task completes correctly and signals initial read completion.")
}

/// Read all complete lines of a file. Returns the lines and the byte offset
/// just after the last complete line.
pub fn read_initial(path: &Path) -> Result<(Vec<String>, u64), Report> {
    let mut file = File::open(path).map_err(|e| open_error(path, e))?;
    let mut data = Vec::new();
    file.read_to_end(&mut data).map_err(|_| initial_read_error())?;
    let last = match data.iter().rposition(|&b| b == b'\n') {
        None => return Ok((Vec::new(), 0)),
        Some(i) => i,
    };
    let mut lines = Vec::new();
    for piece in data[..last].split(|&b| b == b'\n') {
        match std::str::from_utf8(piece) {
            Ok(s) => lines.push(strip_cr(s.to_string())),
            Err(_) => return Err(initial_read_error()),
        }
    }
    Ok((lines, (last + 1) as u64))
}

/// Follow a file from `pos`, writing new lines as they appear. Never returns
/// unless an error occurs.
pub fn follow_file(
    path: &PathBuf,
    mut pos: u64,
    sink: &mut Sink,
    highlighter: &Highlighter,
) -> Result<(), FollowError> {
    let mut file = File::open(path).map_err(|e| FollowError::Report(open_error(path, e)))?;
    let mut pending: Vec<u8> = Vec::new();
    loop {
        let len = match std::fs::metadata(path) {
            Ok(m) => m.len(),
            Err(_) => {
                std::thread::sleep(Duration::from_millis(100));
                continue;
            }
        };
        if len < pos {
            // The file was truncated; start over.
            if let Ok(f) = File::open(path) {
                file = f;
            }
            pos = 0;
        }
        if len > pos {
            if file.seek(SeekFrom::Start(pos)).is_err() {
                std::thread::sleep(Duration::from_millis(100));
                continue;
            }
            let mut chunk = Vec::new();
            let n = (&mut file)
                .take(len - pos)
                .read_to_end(&mut chunk)
                .unwrap_or(0);
            pos += n as u64;
            pending.extend_from_slice(&chunk);
            let mut lines = Vec::new();
            let mut start = 0;
            for (i, &b) in pending.iter().enumerate() {
                if b == b'\n' {
                    lines.push(pending[start..i].to_vec());
                    start = i + 1;
                }
            }
            if start < pending.len() {
                lines.push(pending[start..].to_vec());
            }
            pending.clear();
            let mut out = Vec::new();
            for l in lines {
                match String::from_utf8(l) {
                    Ok(s) => out.push(strip_cr(s)),
                    Err(_) => {
                        return Err(FollowError::Report(
                            Report::new("Could not read next line")
                                .with_cause("stream did not contain valid UTF-8"),
                        ))
                    }
                }
            }
            if !out.is_empty() {
                sink.write_batch(highlighter, &out)
                    .map_err(FollowError::Write)?;
            }
        }
        std::thread::sleep(Duration::from_millis(50));
    }
}

pub enum FollowError {
    Report(Report),
    Write(io::Error),
}
