fn determine_input(cli: &Cli) -> Result<Option<Input>, Report> {
    if let Some(path) = &cli.file {
        if cli.exec.is_some() {
            return Err(Report::new(
                "Cannot read from both file and \x1b[35m--listen-command\x1b[0m",
