        if !path.is_file() {
            return Err(Report::new("Path is not a file"));
        }
        return Ok(Some(Input::File {
            path: path.clone(),
            follow: cli.follow,
        }));
    }
    if !std::io::stdin().is_terminal() {
        return Ok(Some(Input::Stdin));
    }
    if let Some(cmd) = &cli.exec {
        return Ok(Some(Input::Exec(cmd.clone())));
    }
    Ok(None)
}

fn determine_output(cli: &Cli, input: &Input) -> Result<Output, Report> {
    if matches!(input, Input::Stdin) || cli.print {
        return Ok(Output::Stdout);
    }
    match &cli.pager {
        Some(cmd) => match shellwords::split(cmd) {
            Ok(words) if words.len() >= 2 => Ok(Output::Pager(Pager::Custom(words))),
            _ => Err(Report::new("Could not parse custom pager command")),
        },
        None => Ok(Output::Pager(Pager::Default)),
    }
}

fn determine_groups(cli: &Cli) -> Result<Groups, Report> {
    if !cli.enabled.is_empty() && !cli.disabled.is_empty() {
        return Err(Report::new("cannot both enable and disable highlighters"));
    }
    if !cli.enabled.is_empty() {
        let mut g = Groups::all(false);
        for name in &cli.enabled {
            g.set(name, true);
        }
        Ok(g)
    } else {
        let mut g = Groups::all(true);
        for name in &cli.disabled {
            g.set(name, false);
        }
        Ok(g)
    }
}

fn default_config_path() -> Result<PathBuf, Report> {
    let base = match std::env::var("XDG_CONFIG_HOME") {
        Ok(v) => PathBuf::from(v),
        Err(_) => match std::env::var("HOME") {
            Ok(home) => PathBuf::from(home).join(".config"),
            Err(e) => {
                return Err(Report::new(format!(
                    "could not determine the home environment: {}",
                    e
                ))
                .with_cause(e.to_string()))
