            if !p.exists() {
                return Err(Report::new("could not find the TOML file"));
            }
            p.clone()
        }
        None => {
            let p = default_config_path()?;
            if !p.exists() {
                return Ok(Theme::from_toml(TomlTheme::default()));
            }
            p
        }
    };
    let content = std::fs::read_to_string(&path).map_err(|e| {
        Report::new(format!("could not read the TOML file: {}", e)).with_cause(e.to_string())
    })?;
