    Ok(Theme::from_toml(parsed))
}

fn build_highlighter(cli: &Cli, theme: &Theme, groups: Groups) -> Result<Highlighter, Report> {
    let mut keywords = Vec::new();
    if !cli.disable_builtin_keywords {
        keywords.extend(theme::builtin_keywords());
    }
    keywords.extend(theme.keywords.iter().cloned());
    keywords.extend(cli.cli_keywords());
    highlight::build(theme, groups, keywords).map_err(|e| {
        Report::new(format!("Regex error: {}", e))
            .with_cause(e.to_string())
            .with_help("Verify that your regex pattern is valid.")
    })
}

fn run(cli: Cli) -> Result<i32, Report> {
    let input = match determine_input(&cli)? {
        Some(i) => i,
        None => {
            println!("Missing filename (\x1b[36mtspin --help\x1b[0m for help)");
            return Ok(0);
        }
    };
    let output = determine_output(&cli, &input)?;
    let groups = determine_groups(&cli)?;
    let theme = load_theme(&cli)?;
    let highlighter = build_highlighter(&cli, &theme, groups)?;

    match output {
        Output::Stdout => run_stdout(input, &highlighter),
        Output::Pager(pager) => run_pager(input, pager, highlighter),
    }
}

fn broken_pipe(e: &std::io::Error) -> Report {
    eprintln!(
        "\nthread 'tokio-runtime-worker' panicked at library/std/src/io/stdio.rs:\nfailed printing to stdout: {}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        e
    );
    Report::new(format!(
        "task panicked with message \"failed printing to stdout: {}\"",
        e
    ))
}

fn spawn_exec(cmd: &str) -> Result<std::process::Child, Report> {
    Command::new("sh")
        .arg("-c")
        .arg(format!("trap '' INT; {}", cmd))
        .stdout(Stdio::piped())
        .stdin(Stdio::null())
        .spawn()
        .map_err(|e| Report::new(format!("Could not run command: {}", e)))
}

fn run_stdout(input: Input, highlighter: &Highlighter) -> Result<i32, Report> {
    let mut sink = Sink::Stdout;
    match input {
        Input::Stdin => {
            let stdin = std::io::stdin();
            match io::stream_lines(stdin.lock(), &mut sink, highlighter) {
                Ok(()) => Ok(0),
                Err(StreamError::Read(e)) => Err(Report::new(e.to_string())),
                Err(StreamError::Write(e)) => Err(broken_pipe(&e)),
            }
        }
        Input::Exec(cmd) => {
            let mut child = spawn_exec(&cmd)?;
            let stdout = child.stdout.take().unwrap();
            let res = io::stream_lines(stdout, &mut sink, highlighter);
            let _ = child.wait();
            match res {
                Ok(()) => Ok(0),
                Err(StreamError::Read(e)) => Err(Report::new("Could not read next line").with_cause(e.to_string())),
                Err(StreamError::Write(e)) => Err(broken_pipe(&e)),
            }
        }
        Input::File { path, follow } => {
            let (lines, pos) = io::read_initial(&path)?;
            if let Err(e) = sink.write_batch(highlighter, &lines) {
                broken_pipe(&e);
                return Err(io::initial_read_error());
            }
            if !follow {
                return Ok(0);
            }
            match io::follow_file(&path, pos, &mut sink, highlighter) {
                Ok(()) => Ok(0),
                Err(FollowError::Report(r)) => Err(r),
                Err(FollowError::Write(e)) => Err(broken_pipe(&e)),
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Pager

struct TempDir {
    path: PathBuf,
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

fn random_bytes(n: usize) -> Vec<u8> {
    let mut buf = vec![0u8; n];
    let ok = File::open("/dev/urandom")
        .and_then(|mut f| f.read_exact(&mut buf))
        .is_ok();
    if !ok {
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0)
            ^ (std::process::id() as u128) << 64;
        let mut x = seed as u64 | 1;
        for b in buf.iter_mut() {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *b = x as u8;
        }
    }
    buf
}

fn uuid_v4() -> String {
    let mut b = random_bytes(16);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    let hex: String = b.iter().map(|x| format!("{:02x}", x)).collect();
    format!(
        "{}-{}-{}-{}-{}",
        &hex[0..8],
        &hex[8..12],
        &hex[12..16],
        &hex[16..20],
        &hex[20..32]
    )
}

fn create_temp_dir() -> Result<TempDir, Report> {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let base = std::env::temp_dir();
    for _ in 0..100 {
        let name: String = random_bytes(6)
            .iter()
            .map(|b| CHARS[(*b as usize) % CHARS.len()] as char)
            .collect();
        let path = base.join(format!(".tmp{}", name));
        match std::fs::create_dir(&path) {
            Ok(()) => return Ok(TempDir { path }),
            Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(e) => {
                return Err(Report::new("Could not create temporary directory").with_cause(e.to_string()))
            }
        }
    }
    Err(Report::new("Could not create temporary directory"))
}

extern "C" fn ignore_signal(_: libc::c_int) {}

fn run_pager(input: Input, pager: Pager, highlighter: Highlighter) -> Result<i32, Report> {
    let dir = create_temp_dir()?;
    let file_path = dir
        .path
        .join(format!("tailspin.temp.{}", uuid_v4()));
    let file = File::create(&file_path)
        .map_err(|e| Report::new("Could not create temporary file").with_cause(e.to_string()))?;
    let mut sink = Sink::File(file);

    let follow;
    let mut child_cmd: Option<std::process::Child> = None;

    match input {
        Input::File { path, follow: f } => {
            follow = f;
            let (lines, pos) = io::read_initial(&path)?;
            sink.write_batch(&highlighter, &lines)
                .map_err(|_| io::initial_read_error())?;
            if follow {
                let path2 = path.clone();
                std::thread::spawn(move || {
                    let mut sink = sink;
                    match io::follow_file(&path2, pos, &mut sink, &highlighter) {
                        Err(FollowError::Report(r)) => {
                            r.eprint();
                            std::process::exit(1);
                        }
                        _ => {}
                    }
                });
            }
        }
        Input::Exec(cmd) => {
            follow = true;
            let mut child = spawn_exec(&cmd)?;
            let stdout = child.stdout.take().unwrap();
            child_cmd = Some(child);
            std::thread::spawn(move || {
                let mut sink = sink;
                let _ = io::stream_lines(stdout, &mut sink, &highlighter);
            });
        }
        Input::Stdin => unreachable!(),
    }

    let file_str = file_path.to_string_lossy().to_string();
    let mut command = match &pager {
        Pager::Default => {
            let mut c = Command::new("less");
            if follow {
                c.arg("+F");
            }
            c.arg("--ignore-case")
                .arg("--RAW-CONTROL-CHARS")
                .arg("--")
                .arg(&file_str)
                .env("LESSSECURE", "1");
            c
        }
        Pager::Custom(words) => {
            let mut c = Command::new(&words[0]);
            for w in &words[1..] {
                c.arg(w.replace("[FILE]", &file_str));
            }
            c
        }
    };

    unsafe {
        libc::signal(libc::SIGINT, ignore_signal as *const () as libc::sighandler_t);
    }

    let status = command.status();
    if let Some(mut child) = child_cmd {
        let _ = child.kill();
        let _ = child.wait();
    }
    let result = match status {
        Err(e) => Err(Report::new("Could not run pager")
            .with_code("less::command_spawn")
            .with_cause(e.to_string())),
        Ok(st) if !st.success() => Err(Report::new(format!(
            "Pager exited with non-zero status: {}",
            st
        ))
        .with_code("less::non_zero_exit")),
        Ok(_) => Ok(0),
    };
    drop(dir);
    let _ = Path::new(&file_str);
    result
}
