pub struct EmulatedPanic(pub String);

fn thread_id() -> i64 {
    unsafe { libc::syscall(libc::SYS_gettid) as i64 }
}

pub fn emulate_panic(location: &str, msg: String) -> ! {
    use std::io::Write;
    let text = format!(
        "\nthread 'tokio-runtime-worker' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        thread_id(),
        location,
        msg
    );
    let _ = std::io::stderr().write_all(text.as_bytes());
    std::panic::resume_unwind(Box::new(EmulatedPanic(msg)))
}

/// Run `f`, converting an emulated panic into `Err(message)`.
pub fn catch<T, F: FnOnce() -> T>(f: F) -> Result<T, String> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(v) => Ok(v),
        Err(payload) => match payload.downcast::<EmulatedPanic>() {
            Ok(p) => Err(p.0),
            Err(other) => std::panic::resume_unwind(other),
        },
    }
}

pub fn task_panicked(msg: &str) -> crate::report::Report {
    crate::report::Report::new(format!("task 11 panicked with message \"{}\"", msg))
